#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Follow-up dropdown revert + Refraction"
echo " unification + VA/IOP side-by-side split"
echo "=================================================="
echo ""
echo "1) Doctor Follow-up: back to a dropdown (calendar"
echo "   picker reverted). Options: 1 day, 5 days, 10 days,"
echo "   15 days, 3 weeks, 1 month, 2 months, 3 months, SOS."
echo ""
echo "2) OPD Case Sheet Refraction now pulls strictly from"
echo "   Final Rx (matching the finalized optometry"
echo "   prescription exactly) instead of falling back across"
echo "   Objective/Subjective. Same RIGHT EYE/LEFT EYE layout"
echo "   with SPH/CYL/AXIS/PRISM/VISION as the Spectacle"
echo "   Prescription printout -- Dist. and NEAR ADD rows"
echo "   only, no separate Near row (that was a duplicate/"
echo "   contradictory row, now removed to match the"
echo "   Spectacle Prescription exactly)."
echo ""
echo "3) \"ADD\" renamed to \"NEAR ADD\" everywhere: OPD Case"
echo "   Sheet, Spectacle Prescription printout, and the"
echo "   Optometry Final Rx tab UI."
echo ""
echo "4) Vision & IOP on the case sheet split into two"
echo "   side-by-side tables -- VA on the left, IOP on the"
echo "   right. If only one has data, it takes the full row"
echo "   width rather than leaving the other half blank."
echo ""
echo "DATABASE: no new migration needed -- reuses the Prism/"
echo "glasses_type columns and plan_followups.after_period"
echo "column that already exist on both projects."
echo ""

TARGET="app/consultation/[id]/consultation-form.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/(main)/consultation/actions.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/print-templates/actions.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/visit-summary-print/[encounterId]/page.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/(main)/optometry/[id]/optometry-workspace.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

echo ""
echo "Done. Review the diff with:"
echo '  git diff "app/consultation/[id]/consultation-form.js" "app/(main)/consultation/actions.js" app/print-templates/actions.js "app/visit-summary-print/[encounterId]/page.js" "app/(main)/optometry/[id]/optometry-workspace.js"'
echo ""
echo "NOTE: if OPD Case Sheet or Spectacle Prescription have"
echo "ever been customized via the in-app Print Templates"
echo "editor, those saved versions override these code"
echo "defaults -- reset both from that admin page (or I can"
echo "drop the print_templates rows on both projects) for"
echo "this to take effect."
